command:
// ==========================================
// LUNAS WIRKUNG: HERZSCHLAG (ZERZAL)
//
// - lebende Wesen in QS × 5 Schritt wahrnehmen
// - GM bestimmt wahrnehmbare Herzschläge
// - öffentlich nur Richtung + Entfernung
// - unbekannte Herzschläge ergänzbar
// - Effekt zentral über Block 5
// - erneute Konzentration nutzt Effektwerte
// - eine Karte + roter GM-Button über Block 19.8
// - dieselbe Karte wird aktualisiert
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.Wesen?.LebendeInReichweite ||
        !globalThis.DSK?.Geometrie?.PositionInfo ||
        !globalThis.DSK?.Geometrie?.RichtungsAuswahlHtml ||
        !globalThis.DSK?.Geometrie?.SichereRichtung ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.Details;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.Wesen?.LebendeInReichweite ||
        !DSK_FW?.Geometrie?.PositionInfo ||
        !DSK_FW?.Geometrie?.RichtungsAuswahlHtml ||
        !DSK_FW?.Geometrie?.SichereRichtung ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.Details
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework mit Block 19 wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Herzschlag", vollerName = "Herzschlag (Zerzal)", ahne = "Zerzal";
    const reaktionsKey = "herzschlagZerzal", flagKey = "pendingHerzschlagZerzal";
    const endeText = "Das Pochen in deinen Ohren verstummt. Du spürst die Herzschläge in deiner Umgebung nicht mehr.";

    DSK_FW.EffektEnde.Register(reaktionsKey, vollerName, endeText);

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const findeEffekt = actor => actor?.effects?.find(effect =>
        !effect.disabled && (
            effect.getFlag("dsk", "isHerzschlagRadar") === true ||
            String(effect.name || effect.label || "") === vollerName
        )
    ) || null;

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const erstelleAnfrageKarte = async ({
        casterName, qs, radiusMeter, dauerMinuten,
        erneuteKonzentration = false, gmBereich = true,
        anfragenderUserId = game.user.id
    }) => {
        const beschreibung =
            `<b>${casterName}</b> ${erneuteKonzentration
                ? "konzentriert sich erneut auf die Herzschläge in der Umgebung."
                : "lauscht auf die Herzschläge in der Umgebung."}` +
            `<br><br><b>Reichweite:</b> ${radiusMeter} Schritt` +
            `<br><b>Qualitätsstufe:</b> ${qs}` +
            `<br><br>Die Spielleitung entscheidet, welche Herzschläge wahrgenommen werden.`;

        const gmLink = DSK_FW.GabenUI.GMMakroButton(
            macroUuid,
            erneuteKonzentration ? "Neu auf Herzschläge lauschen" : "Effekt anwenden",
            "Das Herzschlag-Makro muss durch die Spielleitung ausgeführt werden."
        );

        return DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
            ziele: [], misserfolge: [], dauerText: `${dauerMinuten} Minuten (QS ${qs})`,
            gmLink, gmBereich, anfragenderUserId
        });
    };

    const aktualisiereErgebnisKarte = async ({
        messageId, casterName, qs, radiusMeter, dauerMinuten, zielInfos
    }) => {
        const message = game.messages.get(messageId);
        if (!message) return false;

        const erfolgreich = zielInfos.length > 0;
        const ergebnisHtml = erfolgreich
            ? `<ul class="dsklist" style="margin:6px 0;">${zielInfos.join("")}</ul>`
            : `<p style="margin:7px 0;text-align:center;color:#555;font-style:italic;">Kein Herzschlag ist wahrnehmbar.</p>`;

        const gabenwirkungHtml = DSK_FW.GabenUI.Details({
            titel: "Gabenwirkung Information",
            inhalt:
                `Das Zerzalkind konzentriert sich auf die Herzschläge lebender Wesen.` +
                `<br><br><b>Reichweite:</b> ${radiusMeter} Schritt` +
                `<br><b>Qualitätsstufe:</b> ${qs}`,
            zentriert: true
        });

        const erneutButton = DSK_FW.GabenUI.GMMakroButton(
            macroUuid,
            "Neu auf Herzschläge lauschen",
            "Das Herzschlag-Makro muss durch die Spielleitung ausgeführt werden."
        );

        await message.update({
            content: `
                ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;">
                    ${gabenwirkungHtml}

                    <hr>

                    <p style="margin:0 0 4px;text-align:left;"><b>Wirkender:</b></p>
                    ${DSK_FW.UI.List([casterName])}

                    <hr>

                    <p style="text-align:center;color:${erfolgreich ? "#18940F" : "#B30000"};font-weight:bold;margin-bottom:7px;">
                        ${erfolgreich ? "Wahrnehmung" : "Keine Herzschläge"}
                    </p>

                    ${ergebnisHtml}

                    <hr>

                    <p style="margin-bottom:0;text-align:center;">
                        <b>Wirkungsdauer:</b> ${dauerMinuten} Minuten (QS ${qs})
                    </p>

                    <section class="secret">
                        <hr>
                        <div style="text-align:center;">
                            <p style="margin:0 0 6px;color:#76301b;font-weight:bold;">
                                Erneute Konzentration
                            </p>

                            <p style="margin:0 0 7px;font-size:.82em;color:#555;line-height:1.35;">
                                Haben sich Wesen bewegt, kann die Spielleitung die Herzschläge erneut bestimmen.
                            </p>

                            ${erneutButton}
                        </div>
                    </section>
                </div>`,
            whisper: [],
            "flags.dsk.gabenAnfrage": true,
            "flags.dsk.gabenName": vollerName,
            "flags.dsk.angewendet": true,
            "flags.dsk.anfragenderUserId": message.getFlag("dsk", "anfragenderUserId") || game.user.id
        });

        return true;
    };

    // +++ 4 - GM-VERARBEITUNG +++++++++++++++++++++++++++++++++

    const verarbeiteHerzschlag = async (casterActor, casterToken, daten = {}) => {
        if (!casterActor || !casterToken) {
            ui.notifications.warn("Luna sagt 🌙: Wirkender oder Token wurde nicht gefunden!");
            return false;
        }

        // +++ 4.1 - WERTE + KANDIDATEN +++++++++++++++++++++++++

        const bestehenderEffekt = findeEffekt(casterActor);
        const qs = Math.max(1, Math.floor(Number(
            daten.qs || bestehenderEffekt?.getFlag("dsk", "qsWert") || 1
        ) || 1));

        const radiusMeter = Math.max(1, Number(
            daten.radiusMeter || bestehenderEffekt?.getFlag("dsk", "radiusMeter") || qs * 5
        ));

        const dauerMinuten = Math.max(1, Number(
            daten.dauerMinuten || bestehenderEffekt?.getFlag("dsk", "dauerMinuten") || qs
        ));

        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);

        const kandidaten = DSK_FW.Wesen.LebendeInReichweite(casterToken, radiusMeter)
            .map(token => {
                const position = DSK_FW.Geometrie.PositionInfo(casterToken, token, { nachkommastellen: 1 });
                return { token, ...position };
            })
            .sort((a, b) =>
                a.distanz - b.distanz ||
                String(a.token.name).localeCompare(String(b.token.name), "de")
            );

        const kandidatenHtml = kandidaten.length
            ? kandidaten.map(eintrag => `
                <label style="display:flex;align-items:flex-start;gap:7px;margin-bottom:6px;padding:6px 8px;background:rgba(255,255,255,.35);border-radius:3px;cursor:pointer;">
                    <input type="checkbox" name="herzschlag" value="${eintrag.token.id}">

                    <span style="flex:1;">
                        <b>${eintrag.token.name}</b><br>
                        <span style="font-size:.82em;color:#555;">
                            ca. ${eintrag.distanz} Schritt, ${eintrag.richtung} (${eintrag.richtungKurz})
                        </span>
                    </span>
                </label>`).join("")
            : `<p style="margin:0;color:#555;font-style:italic;">Keine lebenden Wesen innerhalb der Reichweite.</p>`;

        // +++ 4.2 - GM-AUSWAHL ++++++++++++++++++++++++++++++++

        const dialogResult = await foundry.applications.api.DialogV2.wait({
            window: { title: vollerName },
            position: { width: 520 },

            content: `<form>
                <div style="font-family:'Signika',sans-serif;">
                    ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}

                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="margin:0 0 8px;">
                            <b>${casterName}</b> konzentriert sich auf die Herzschläge in der Umgebung.
                        </p>

                        ${DSK_FW.UI.List([
                            `<b>QS:</b> ${qs}`,
                            `<b>Reichweite:</b> ${radiusMeter} Schritt`,
                            `<b>Wirkungsdauer:</b> ${dauerMinuten} Minuten`
                        ])}

                        <hr>

                        <p style="margin:0 0 7px;font-weight:bold;">
                            Welche platzierten Herzschläge werden wahrgenommen?
                        </p>

                        <div style="max-height:200px;overflow-y:auto;padding:8px;background:rgba(0,0,0,.05);border-radius:4px;">
                            ${kandidatenHtml}
                        </div>

                        <hr>

                        <div style="padding:8px 10px;background:rgba(118,48,27,.06);border:1px solid rgba(118,48,27,.2);border-radius:4px;">
                            <p style="margin:0 0 8px;font-weight:bold;">
                                Unbekannte oder nicht platzierte Herzschläge
                            </p>

                            <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
                                <label for="unbekannteAnzahl" style="min-width:70px;">Anzahl:</label>

                                <input id="unbekannteAnzahl" name="unbekannteAnzahl" type="number"
                                    value="0" min="0" max="20" step="1"
                                    style="width:65px;text-align:center;">
                            </div>

                            <p style="margin:0 0 5px;font-size:.9em;font-weight:bold;">
                                Richtung:
                            </p>

                            ${DSK_FW.Geometrie.RichtungsAuswahlHtml({
                                name: "unbekannteRichtung",
                                vorauswahl: "Norden"
                            })}

                            <div style="display:flex;align-items:center;gap:8px;margin-top:8px;">
                                <label for="unbekannteEntfernung" style="min-width:70px;">Entfernung:</label>

                                <input id="unbekannteEntfernung" name="unbekannteEntfernung" type="number"
                                    value="1" min="0" max="${radiusMeter}" step="1"
                                    style="width:65px;text-align:center;">

                                <span>Schritt</span>
                            </div>
                        </div>

                        <hr>

                        <p style="margin:0;font-size:.85em;color:#555;">
                            <i>
                                Die Namen sind nur für die Spielleitung sichtbar.
                                Das Ergebnis zeigt ausschließlich Richtung und Entfernung.
                            </i>
                        </p>
                    </div>
                </div>
            </form>`,

            buttons: [
                {
                    action: "ok",
                    label: "Wahrnehmung bestätigen",
                    icon: "fas fa-heartbeat",
                    default: true,

                    callback: event => {
                        const form = event.target.closest("form");

                        if (!form) {
                            return {
                                selectedIds: [],
                                unbekannteAnzahl: 0,
                                unbekannteRichtung: "Norden",
                                unbekannteEntfernung: 1
                            };
                        }

                        const formData = new FormData(form);

                        return {
                            selectedIds: Array.from(
                                form.querySelectorAll('input[name="herzschlag"]:checked')
                            ).map(element => element.value),

                            unbekannteAnzahl: Math.max(
                                0,
                                Math.min(
                                    20,
                                    Math.floor(
                                        Number(formData.get("unbekannteAnzahl")) || 0
                                    )
                                )
                            ),

                            unbekannteRichtung: DSK_FW.Geometrie.SichereRichtung(
                                formData.get("unbekannteRichtung"),
                                "Norden"
                            ),

                            unbekannteEntfernung: Math.max(
                                0,
                                Math.min(
                                    radiusMeter,
                                    Math.floor(
                                        Number(formData.get("unbekannteEntfernung")) || 0
                                    )
                                )
                            )
                        };
                    }
                },
                {
                    action: "cancel",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => null
                }
            ],

            rejectClose: false
        });

        if (!dialogResult) {
            ui.notifications.info(
                "Luna sagt 🌙: Die Herzschlag-Auswahl wurde abgebrochen. Die Anfrage bleibt erhalten."
            );
            return false;
        }

        const {
            selectedIds = [],
            unbekannteAnzahl = 0,
            unbekannteRichtung = "Norden",
            unbekannteEntfernung = 1
        } = dialogResult;

        const ausgewaehlt = selectedIds
            .map(id => canvas.tokens.get(id))
            .filter(token =>
                token?.actor &&
                DSK_FW.Wesen.IstLebendig(token.actor) &&
                DSK_FW.Geometrie.Distanz(casterToken, token) <= radiusMeter
            );

        // +++ 4.3 - EFFEKT ÜBER BLOCK 5 ++++++++++++++++++++++++

        let herzschlagEffekt = bestehenderEffekt;

        if (!herzschlagEffekt) {
            herzschlagEffekt = await DSK_FW.Effekt.Anwenden({
                name: vollerName,
                ahne,

                beschreibung:
                    `<b>${casterName}</b> spürt den Herzschlag lebender Wesen in einem Umkreis von ` +
                    `<b>${radiusMeter} Schritt</b> und kann deren ungefähre Richtung und Entfernung einschätzen.`,

                gabeZiel: "erwachte",
                qs,
                ziel: casterActor,

                flags: {
                    dsk: {
                        isHerzschlagRadar: true,
                        schadensReaktion: reaktionsKey,
                        casterUuid: casterActor.uuid,
                        qsWert: qs,
                        radiusMeter,
                        dauerMinuten,
                        casterName,
                        basisName: gabenName,
                        ahne,

                        wirkungsende: {
                            sfName: reaktionsKey,
                            basisEffektName: vollerName,
                            beschreibungFuerEnde: endeText
                        }
                    }
                },

                duration: {
                    seconds: dauerMinuten * 60,
                    startTime: game.time.worldTime
                }
            });
        }

        if (!herzschlagEffekt) {
            await aktualisiereErgebnisKarte({
                messageId: daten.messageId,
                casterName,
                qs,
                radiusMeter,
                dauerMinuten,
                zielInfos: []
            });

            ui.notifications.error(
                "Luna sagt 🌙: Der Herzschlag-Effekt konnte nicht angelegt werden!"
            );

            return true;
        }

        // +++ 4.4 - ANONYMES ERGEBNIS +++++++++++++++++++++++++

        const zielInfos = [];

        for (const token of ausgewaehlt) {
            const position = DSK_FW.Geometrie.PositionInfo(
                casterToken,
                token,
                { nachkommastellen: 0 }
            );

            zielInfos.push(
                `<li>Herzschlag ca. <b>${position.distanz} Schritt</b> entfernt im ` +
                `<b>${position.richtung}</b></li>`
            );
        }

        if (unbekannteAnzahl > 0) {
            zielInfos.push(
                `<li>${unbekannteAnzahl === 1
                    ? "Ein weiterer Herzschlag"
                    : `<b>${unbekannteAnzahl}</b> weitere Herzschläge`} ` +
                `ca. <b>${unbekannteEntfernung} Schritt</b> entfernt im ` +
                `<b>${unbekannteRichtung}</b></li>`
            );
        }

        await aktualisiereErgebnisKarte({
            messageId: daten.messageId,
            casterName,
            qs,
            radiusMeter,
            dauerMinuten,
            zielInfos
        });

        return true;
    };

    // +++ 5 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const casterActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(casterActor, flagKey);
                if (!daten) continue;

                if (
                    daten.sceneId &&
                    daten.sceneId !== canvas.scene?.id
                ) {
                    ui.notifications.warn(
                        `Luna sagt 🌙: Die Herzschlag-Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
                    );
                    continue;
                }

                const casterToken = DSK_FW.Token.Finde(
                    casterActor,
                    daten.casterTokenId,
                    daten.casterTokenUuid
                );

                if (!casterToken) {
                    ui.notifications.warn(
                        `Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden.`
                    );
                    continue;
                }

                if (
                    await verarbeiteHerzschlag(
                        casterActor,
                        casterToken,
                        daten
                    )
                ) {
                    await DSK_FW.GMAnfrage.Loeschen(
                        casterActor,
                        flagKey
                    );
                }
            }

            return;
        }

        // +++ 5.1 - ERNEUTE KONZENTRATION +++++++++++++++++++++

        let casterActor = canvas.tokens.controlled[0]?.actor || null;

        if (!casterActor) {
            casterActor = canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor => findeEffekt(actor)) || null;
        }

        if (!casterActor) {
            return ui.notifications.warn(
                "Luna sagt 🌙: Kein aktiver Herzschlag-Träger wurde gefunden. Bitte wähle dessen Token aus!"
            );
        }

        const effekt = findeEffekt(casterActor);

        if (!effekt) {
            return ui.notifications.warn(
                "Luna sagt 🌙: Der ausgewählte Akteur besitzt keinen aktiven Herzschlag-Effekt!"
            );
        }

        const casterToken = DSK_FW.Token.Finde(casterActor);

        if (!casterToken) {
            return ui.notifications.warn(
                "Luna sagt 🌙: Der Herzschlag-Träger besitzt kein aktives Token auf der Szene!"
            );
        }

        const qs = Math.max(
            1,
            Number(effekt.getFlag("dsk", "qsWert")) || 1
        );

        const radiusMeter = Math.max(
            1,
            Number(effekt.getFlag("dsk", "radiusMeter")) || qs * 5
        );

        const dauerMinuten = Math.max(
            1,
            Number(effekt.getFlag("dsk", "dauerMinuten")) || qs
        );

        const casterName = DSK_FW.ResolveTokenName(casterActor);

        const nachricht = await erstelleAnfrageKarte({
            casterName,
            qs,
            radiusMeter,
            dauerMinuten,
            erneuteKonzentration: true,
            gmBereich: false,
            anfragenderUserId: game.user.id
        });

        if (!nachricht) {
            return ui.notifications.error(
                "Luna sagt 🌙: Die Herzschlag-Karte konnte nicht erstellt werden!"
            );
        }

        await verarbeiteHerzschlag(
            casterActor,
            casterToken,
            {
                qs,
                radiusMeter,
                dauerMinuten,
                casterName,
                casterTokenId: casterToken.id,
                casterTokenUuid:
                    casterToken.document?.uuid ||
                    casterToken.uuid ||
                    null,
                sceneId: canvas.scene?.id || null,
                requestedByUserId: game.user.id,
                macroUuid,
                erneuteKonzentration: true,
                messageId: nachricht.id
            }
        );

        return;
    }

    // +++ 6 - SPIELERAUSFÜHRUNG +++++++++++++++++++++++++++++++

    let casterActor =
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor =>
                    actor?.getFlag(
                        "world",
                        "letzteGabenQS"
                    ) !== undefined
                ) ||
            game.actors.find(actor =>
                actor.getFlag(
                    "world",
                    "letzteGabenQS"
                ) !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle zuerst den Token des Wirkenden aus!"
        );
    }

    if (!casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);

    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Konnte das Token des Wirkenden nicht finden!"
        );
    }

    const effekt = findeEffekt(casterActor);
    const erneuteKonzentration = Boolean(effekt);

    const qs = effekt
        ? Math.max(
            1,
            Math.floor(
                Number(
                    effekt.getFlag(
                        "dsk",
                        "qsWert"
                    )
                ) || 1
            )
        )
        : DSK_FW.QS.Ermitteln({
            actor: casterActor,
            gabenName,
            suchbegriffe: [
                "Herzschlag Probe",
                "Herzschlag"
            ],
            testDataObj:
                typeof testData !== "undefined"
                    ? testData
                    : null,
            fallback: 0,
            protokollieren: true
        });

    if (qs <= 0) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Die Qualitätsstufe der Herzschlag-Probe konnte nicht ermittelt werden!"
        );
    }

    const radiusMeter = effekt
        ? Math.max(
            1,
            Number(
                effekt.getFlag(
                    "dsk",
                    "radiusMeter"
                )
            ) || qs * 5
        )
        : qs * 5;

    const dauerMinuten = effekt
        ? Math.max(
            1,
            Number(
                effekt.getFlag(
                    "dsk",
                    "dauerMinuten"
                )
            ) || qs
        )
        : qs;

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 6.1 - GEMEINSAME KARTE + ROTER GM-BUTTON +++++++++++

    const nachricht = await erstelleAnfrageKarte({
        casterName,
        qs,
        radiusMeter,
        dauerMinuten,
        erneuteKonzentration,
        gmBereich: true,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        return ui.notifications.error(
            "Luna sagt 🌙: Die Herzschlag-Karte konnte nicht erstellt werden!"
        );
    }

    // +++ 6.2 - ANFRAGE SPEICHERN +++++++++++++++++++++++++++++

    const anfrageDaten = {
        qs,
        radiusMeter,
        dauerMinuten,
        casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid:
            casterToken.document?.uuid ||
            casterToken.uuid ||
            null,
        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        macroUuid,
        erneuteKonzentration,
        messageId: nachricht.id
    };

    await DSK_FW.GMAnfrage.Speichern(
        casterActor,
        flagKey,
        anfrageDaten
    );

    await raeumeQSAuf(casterActor);

    ui.notifications.info(
        "Luna sagt 🌙: Herzschlag wurde bei der Spielleitung beantragt."
    );

}).call(this);
